import sys; sys.path.insert(0,'/workspace/src')
import numpy as np, base64, json
from ft2api import ft2, measure
def pcm_b64(x, enc='int16'):
    if enc=='int16':
        a=(np.clip(x,-1,1)*32767).astype('<i2').tobytes()
    else:
        a=np.asarray(x,dtype='<f4').tobytes()
    return base64.b64encode(a).decode()
# test 1: create_from_pcm natural pitch + assumed rate 44100, note mapping
t=np.arange(int(44100*1.0),dtype=np.float64)/44100
x=np.sin(2*np.pi*220*t)*np.minimum(1,t/0.004)*0.7
ft2('module_new',{'channels':2,'name':'pcm test'})
print(ft2('sample_create_from_pcm',{'instrument':1,'sample':0,'pcm':pcm_b64(x),'name':'T220'}))
